"""Load Task configuration files and TASK_* environment overrides."""
import os
from pathlib import Path


BOOLS = {
    'verbose': 'TASK_VERBOSE', 'silent': 'TASK_SILENT', 'color': 'TASK_COLOR',
    'disable-fuzzy': 'TASK_DISABLE_FUZZY', 'failfast': 'TASK_FAILFAST',
    'dry': 'TASK_DRY', 'assume-yes': 'TASK_ASSUME_YES',
    'interactive': 'TASK_INTERACTIVE',
}


def _scalar(value):
    value = value.split(' #', 1)[0].strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in "'\"":
        value = value[1:-1]
    low = value.lower()
    if low in ('true', 'yes', 'on'): return True
    if low in ('false', 'no', 'off'): return False
    if low in ('null', '~', ''): return None
    try: return int(value)
