"""Taskfile location helpers, independent of the YAML loader."""
from pathlib import Path

NAMES = (
    "Taskfile.yml", "taskfile.yml", "Taskfile.yaml", "taskfile.yaml",
    "Taskfile.dist.yml", "taskfile.dist.yml", "Taskfile.dist.yaml", "taskfile.dist.yaml",
)


def find_taskfile(directory='.', explicit=None, global_file=False, home=None):
    """Return (path, execution_root), or (None, directory) if not found.

    Automatic lookup walks toward filesystem root, matching Task's behavior.
    Explicit paths are resolved relative to the selected working directory.
    """
    start = Path(home if global_file and home else directory).expanduser().resolve()
    if explicit is not None:
        if explicit == '-':
            return '-', str(start)
        p = Path(explicit).expanduser()
        if not p.is_absolute():
            p = start / p
        if p.is_dir():
            for name in NAMES:
                candidate = p / name
                if candidate.is_file():
                    return str(candidate.resolve()), str(p.resolve())
        return str(p.resolve()), str(p.resolve().parent)
    current = start
    try: owner = current.stat().st_uid
    except OSError: owner = None
    while True:
        for name in NAMES:
            candidate = current / name
            if candidate.is_file():
                return str(candidate.resolve()), str(current)
        if current.parent == current:
            break
        try:
            if owner is not None and current.parent.stat().st_uid != owner:
                break
        except OSError:
            break
        current = current.parent
    return None, str(start)

